import {esc} from './render.js';
import {uiIcon} from './ui-icons.js';
export const colorValue=v=>v==='none'?'none':/^#[\da-f]{6}$/i.test(v)?v.toLowerCase():/^#[\da-f]{3}$/i.test(v)?'#'+[...v.slice(1)].map(c=>c+c).join('').toLowerCase():null;
export function rgb(hex){const v=colorValue(hex);return v&&v!=='none'?[1,3,5].map(i=>parseInt(v.slice(i,i+2),16)):[255,255,255];}
export function fromRgb(r,g,b){return '#'+[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');}
export function hsv(hex){const [r,g,b]=rgb(hex).map(v=>v/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d)h=max===r?((g-b)/d)%6:max===g?(b-r)/d+2:(r-g)/d+4;return {h:(h*60+360)%360,s:max?d/max:0,v:max};}
export function fromHsv(h,s,v){const c=v*s,x=c*(1-Math.abs(h/60%2-1)),m=v-c,sets=[[c,x,0],[x,c,0],[0,c,x],[0,x,c],[x,0,c],[c,0,x]];return fromRgb(...sets[Math.min(5,Math.floor(h/60))].map(n=>(n+m)*255));}
export function rememberColor(state,value){if(value!=='none')state.recent=[value,...state.recent.filter(v=>v!==value)].slice(0,12);}
export function colorPalette(state){const value=state[state.target]||'#ffffff',v=hsv(value),channels=rgb(value),swatch=c=>`<button class="color-swatch ${c==='none'?'no-color':''}" style="--swatch:${c==='none'?'transparent':c}" data-color="${c}" aria-label="${c==='none'?'Sin relleno':c}" title="${c==='none'?'Sin relleno':c}"></button>`;return `<header class="floating-header"><strong>${uiIcon('fill')}Color</strong><button data-color-close aria-label="Cerrar color">${uiIcon('close')}</button></header><div class="floating-body"><div class="color-targets"><button data-color-target="fill" class="${state.target==='fill'?'active':''}">Relleno</button><button data-color-target="stroke" class="${state.target==='stroke'?'active':''}">Línea</button></div><div class="color-sv" data-color-sv style="--hue:${fromHsv(v.h,1,1)}"><i style="left:${v.s*100}%;top:${(1-v.v)*100}%"></i></div><input type="range" class="color-hue" data-color-hue min="0" max="359" value="${v.h}" aria-label="Tono"><div class="fields"><label class="field full">HEX<input data-color-hex value="${esc(value)}" spellcheck="false"></label>${channels.map((c,i)=>`<label class="field">${['R','G','B'][i]}<input type="number" data-color-rgb="${i}" min="0" max="255" value="${c}"></label>`).join('')}<label class="field">Opacidad %<input type="number" data-color-opacity min="0" max="100" value="${state.opacity*100}"></label><label class="field full">Opacidad<input type="range" data-color-opacity min="0" max="100" value="${state.opacity*100}" aria-label="Opacidad de relleno"></label><label class="field full">Aplicar a<select data-color-view><option value="this" ${state.applyTo==='this'?'selected':''}>Esta vista</option><option value="both" ${state.applyTo==='both'?'selected':''}>Vistas vinculadas</option></select></label></div><div class="color-swatches">${swatch('none')}${state.recent.map(swatch).join('')}</div><h4>Muestras del documento</h4><div class="color-swatches">${state.swatches.map(swatch).join('')}<button data-add-swatch aria-label="Agregar color a muestras">${uiIcon('plus')}</button></div><button class="secondary" data-apply-color>Aplicar a selección</button></div>`;}
export function bindColorPicker(host,current,onColor,transaction={}){let h=hsv(current),draft=current,active=false;const sv=host.querySelector('[data-color-sv]'),hue=host.querySelector('[data-color-hue]');if(!sv||!hue)return;const begin=()=>{if(active)return true;if(transaction.begin?.()===false)return false;active=true;return true;};const preview=()=>{draft=fromHsv(h.h,h.s,h.v);sv.style.setProperty('--hue',fromHsv(h.h,1,1));const indicator=sv.querySelector('i');indicator.style.left=h.s*100+'%';indicator.style.top=(1-h.v)*100+'%';host.querySelector('[data-color-hex]').value=draft;rgb(draft).forEach((v,i)=>host.querySelector(`[data-color-rgb="${i}"]`).value=v);transaction.update?.(draft);};const update=e=>{const r=sv.getBoundingClientRect();h.s=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));h.v=1-Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));preview();};const finish=()=>{if(!active)return;active=false;if(transaction.commit)transaction.commit();else onColor(draft);};sv.onpointerdown=e=>{e.preventDefault();if(!begin())return;sv.setPointerCapture(e.pointerId);update(e);sv.onpointermove=update;};sv.onpointerup=e=>{update(e);sv.onpointermove=null;finish();if(sv.hasPointerCapture?.(e.pointerId))sv.releasePointerCapture(e.pointerId);};sv.onpointercancel=sv.onlostpointercapture=()=>{if(!active)return;sv.onpointermove=null;active=false;transaction.cancel?.();};hue.onpointerdown=begin;hue.oninput=()=>{if(!begin())return;h.h=+hue.value;preview();};hue.onchange=finish;hue.onpointercancel=()=>{active=false;transaction.cancel?.();};}
